    return 0;
}

additionalExercises.referenceSolution:
#include <iostream>
#include <map>
#include <string>

int main() {
    std::map<std::string, std::string> book;
    std::string command;
    while (std::cin >> command) {
        if (command == "add") {
            std::string name, phone;
            std::cin >> name >> phone;
            book[name] = phone;
        } else if (command == "del") {
            std::string name;
            std::cin >> name;
            std::cout << (book.erase(name) > 0 ? "удалено" : "нет такого") << '\n';
        } else if (command == "find") {
            std::string name;
            std::cin >> name;
            auto it = book.find(name);
            std::cout << (it != book.end() ? it->second : "нет такого") << '\n';
        } else if (command == "list") {
            if (book.empty()) {
                std::cout << "пусто\n";
            }
            for (const auto &[name, phone] : book) {
                std::cout << name << ' ' << phone << '\n';
            }
        }
    }
    return 0;
}

